PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE students (
                chat_id    TEXT PRIMARY KEY,
                naam       TEXT,
                branch     TEXT,
                roll_no    TEXT,
                unique_id  TEXT UNIQUE,
                registered_at TEXT DEFAULT (datetime('now'))
            , year TEXT);
CREATE TABLE attendance (
                date       TEXT,
                chat_id    TEXT,
                status     TEXT NOT NULL,
                marked_by  TEXT NOT NULL DEFAULT 'self',
                PRIMARY KEY (date, chat_id),
                FOREIGN KEY (chat_id) REFERENCES students(chat_id)
            );
CREATE TABLE holiday_notices (
                date       TEXT PRIMARY KEY,
                notice     BLOB,
                type       TEXT NOT NULL,
                saved_by   TEXT NOT NULL
            );
CREATE TABLE api_tokens (
                   token      TEXT PRIMARY KEY,
                   chat_id    TEXT NOT NULL,
                   created_at TEXT DEFAULT (datetime('now'))
               );
CREATE INDEX idx_students_roll
                ON students(roll_no);
CREATE INDEX idx_students_branch
                ON students(branch);
CREATE INDEX idx_att_chat
                ON attendance(chat_id);
COMMIT;
